// Generates crates/opencode/src/generated/database.rs from the TS reference's database bootstrap: the exact DDL a
// fresh database is created with (packages/core/src/database/schema.gen.ts) and the IDs of every migration it records
// as applied (migration.gen.ts), so a database the Rust server creates is the one the TS server creates.
//
// usage: bun src/database.ts            write the generated file
//        bun src/database.ts --check    fail if the checked-in file differs from a fresh generation
import { readFileSync, mkdirSync, writeFileSync } from "node:fs"
import { join, resolve } from "node:path"
import { Effect } from "effect"

const ref = resolve(process.env.REFERENCE ?? join(import.meta.dir, "../../../.reference"))
const database = join(ref, "packages/core/src/database")
const schema = (await import(join(database, "schema.gen.ts"))).default as {
  up: (tx: unknown) => Effect.Effect<void, unknown, never>
}
const { migrations } = (await import(join(database, "migration.gen.ts"))) as { migrations: { id: string }[] }

// schema.gen.ts only runs plain SQL text through the transaction.
const statements: string[] = []
const tx = {
  run(statement: unknown) {
    if (typeof statement !== "string") throw new Error(`schema.gen.ts ran a non-text statement: ${String(statement)}`)
    statements.push(statement)
    return Effect.void
  },
}
await Effect.runPromise(schema.up(tx))

// The bootstrap also runs the legacy credential import (a data migration, reproduced by hand in the server); fail
// when upstream adds another step the Rust bootstrap would not know about.
const source = readFileSync(join(database, "migration.ts"), "utf8")
const bootstrap = source.slice(source.indexOf("export function apply("), source.indexOf("export function applyOnly("))
const steps = [...bootstrap.matchAll(/yield\* (\w+)\.up\(tx\)/g)].map((match) => match[1])
if (JSON.stringify(steps) !== JSON.stringify(["schema", "legacyCredentials"]))
  throw new Error(`the database bootstrap runs ${steps.join(", ")}; update port/rust/gen/src/database.ts`)

const literal = (text: string) => `r#"${text}"#`
const out = `// @generated by port/rust/gen (port/scripts/gen-types.sh) from the TS reference's database bootstrap.
// Do not edit: regenerate instead. See port/README.md.

/// The DDL a fresh database is created with, in order (packages/core/src/database/schema.gen.ts), byte for byte.
pub const SCHEMA: &[&str] = &[
${statements.map((statement) => `    ${literal(statement)},`).join("\n")}
];

/// Every migration, in order (migration.gen.ts). A fresh database records them all as applied.
pub const MIGRATIONS: &[&str] = &[
${migrations.map((migration) => `    ${JSON.stringify(migration.id)},`).join("\n")}
];
`

const file = join(import.meta.dir, "../../crates/opencode/src/generated/database.rs")
if (process.argv.includes("--check")) {
  let current = ""
  try {
    current = readFileSync(file, "utf8")
  } catch {}
  if (current !== out) {
    console.error("generated database bootstrap is stale; run port/scripts/gen-types.sh")
    process.exit(1)
  }
  console.log(`database bootstrap is up to date (${statements.length} statements, ${migrations.length} migrations)`)
} else {
  mkdirSync(join(file, ".."), { recursive: true })
  writeFileSync(file, out)
  console.log(`database bootstrap: ${statements.length} statements, ${migrations.length} migrations`)
}
